"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Cpu, ArrowLeft, Save } from "lucide-react";
import Link from "next/link";

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

export default function AddSmartMeterPage() {
  const router = useRouter();

  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
  smartMeterId: "",
  location: "",
  latitude: "",
  longitude: "",
  status: "Active",

  mediaConverters: [
    {
      mediaConverterId: "",
      ipAddress: "",
      location: "",
    },
  ],
});

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    try {
      setLoading(true);

      const result = await createSmartMeter({
  smartMeterId: formData.smartMeterId,
  location: formData.location,
  latitude: formData.latitude
    ? Number(formData.latitude)
    : null,
  longitude: formData.longitude
    ? Number(formData.longitude)
    : null,
  status: formData.status,

  mediaConverters: formData.mediaConverters,
});

if (!result.success) {
  throw new Error(
    result.error || "Failed to create Smart Meter"
  );
}

router.push("/smartmeter");
    
    } catch (error) {
      console.error(error);
      alert(
        error instanceof Error
          ? error.message
          : "Failed to create Smart Meter"
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-[#111] p-6">
      <div className="mx-auto max-w-3xl">
        {/* Header */}
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h1 className="flex items-center gap-3 text-3xl font-bold text-white">
              <Cpu className="h-8 w-8 text-cyan-400" />
              Add Smart Meter
            </h1>

            <p className="mt-2 text-sm text-gray-400">
              Create a new Smart Meter
            </p>
          </div>

          <Link
            href="/smartmeter"
            className="
              flex items-center gap-2
              rounded-lg
              border border-[#333]
              bg-[#1a1a1a]
              px-4 py-2
              text-sm text-gray-300
              transition
              hover:border-cyan-500
              hover:text-white
            "
          >
            <ArrowLeft className="h-4 w-4" />
            Back
          </Link>
        </div>

        {/* Form */}
        <div className="rounded-2xl border border-[#333] bg-[#1a1a1a] p-6">
          <form
            onSubmit={handleSubmit}
            className="space-y-6"
          >
            {/* Smart Meter ID */}
            <div>
              <label className="mb-2 block text-sm font-medium text-gray-300">
                Smart Meter ID *
              </label>

              <input
                required
                type="text"
                value={formData.smartMeterId}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    smartMeterId: e.target.value,
                  })
                }
                placeholder="SM-001"
                className="
                  w-full
                  rounded-lg
                  border border-[#333]
                  bg-[#111]
                  px-4 py-3
                  text-white
                  outline-none
                  focus:border-cyan-500
                "
              />
            </div>

            {/* Location */}
            <div>
              <label className="mb-2 block text-sm font-medium text-gray-300">
                Location
              </label>

              <input
                type="text"
                value={formData.location}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    location: e.target.value,
                  })
                }
                placeholder="North Sector"
                className="
                  w-full
                  rounded-lg
                  border border-[#333]
                  bg-[#111]
                  px-4 py-3
                  text-white
                  outline-none
                  focus:border-cyan-500
                "
              />
            </div>

            {/* Coordinates */}
            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <label className="mb-2 block text-sm font-medium text-gray-300">
                  Latitude
                </label>

                <input
                  type="number"
                  step="any"
                  value={formData.latitude}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      latitude: e.target.value,
                    })
                  }
                  placeholder="19.0760"
                  className="
                    w-full
                    rounded-lg
                    border border-[#333]
                    bg-[#111]
                    px-4 py-3
                    text-white
                    outline-none
                    focus:border-cyan-500
                  "
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-medium text-gray-300">
                  Longitude
                </label>

                <input
                  type="number"
                  step="any"
                  value={formData.longitude}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      longitude: e.target.value,
                    })
                  }
                  placeholder="72.8777"
                  className="
                    w-full
                    rounded-lg
                    border border-[#333]
                    bg-[#111]
                    px-4 py-3
                    text-white
                    outline-none
                    focus:border-cyan-500
                  "
                />
              </div>
            </div>

            {/* Status */}
            <div>
              <label className="mb-2 block text-sm font-medium text-gray-300">
                Status
              </label>

              <select
                value={formData.status}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    status: e.target.value,
                  })
                }
                className="
                  w-full
                  rounded-lg
                  border border-[#333]
                  bg-[#111]
                  px-4 py-3
                  text-white
                  outline-none
                  focus:border-cyan-500
                "
              >
                <option value="Active">Active</option>
                <option value="Inactive">Inactive</option>
              </select>
            </div>

            {/* Submit */}
            <div className="flex justify-end">
              <button
                type="submit"
                disabled={loading}
                className="
                  flex items-center gap-2
                  rounded-lg
                  bg-cyan-600
                  px-5 py-3
                  text-white
                  transition
                  hover:bg-cyan-500
                  disabled:opacity-50
                "
              >
                <Save className="h-4 w-4" />

                {loading
                  ? "Creating..."
                  : "Create Smart Meter"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}